import React from "react";

import {
  filterSelector,
  SortsList,
  setSort,
  TSort,
} from "../redux/slices/filterSlice";

import { useSelector, useDispatch } from "react-redux";

import { useTranslation } from "react-i18next";

const Sort: React.FC = () => {
  const { t, i18n } = useTranslation();

  const dispatch = useDispatch();

  const sortRef = React.useRef<HTMLDivElement>(null);

  const { sort } = useSelector(filterSelector);

  const [isVisible, setIsVisible] = React.useState(false);

  React.useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      const current = sortRef.current;
      const path = e.composedPath();

      if (current && !path.includes(current)) {
        setIsVisible(false);
      }
    };

    document.body.addEventListener("click", handleClickOutside);

    return () => {
      document.body.removeEventListener("click", handleClickOutside);
    };
  }, []);

  const onClickChangeSort = (obj: TSort) => {
    dispatch(setSort(obj));
    setIsVisible(false);
  };

  return (
    <div className="filters">
      <div ref={sortRef} className="sort">
        <div className="sort__label">
          <svg
            width="10"
            height="6"
            viewBox="0 0 10 6"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M10 5C10 5.16927 9.93815 5.31576 9.81445 5.43945C9.69075 5.56315 9.54427 5.625 9.375 5.625H0.625C0.455729 5.625 0.309245 5.56315 0.185547 5.43945C0.061849 5.31576 0 5.16927 0 5C0 4.83073 0.061849 4.68424 0.185547 4.56055L4.56055 0.185547C4.68424 0.061849 4.83073 0 5 0C5.16927 0 5.31576 0.061849 5.43945 0.185547L9.81445 4.56055C9.93815 4.68424 10 4.83073 10 5Z"
              fill="#a79579"
            />
          </svg>
          <b>{t("sort")}:</b>
          <span className="sort-span" onClick={() => setIsVisible(!isVisible)}>
            {t(sort.name)}
          </span>
        </div>
        {isVisible && (
          <div className="sort__popup">
            <ul>
              {SortsList.map((obj) => (
                <li
                  key={obj.type}
                  onClick={() => onClickChangeSort(obj)}
                  className={sort.type === obj.type ? "active" : ""}
                >
                  {t(obj.name)}
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </div>
  );
};

export default Sort;
